144	    #[test]
145	    fn point_add() {
146	        let g = Affine::<BandersnatchConfig>::generator();
147	        let g_proj: Projective<BandersnatchConfig> = g.into();
148	
149	        // Test G + G = 2G
150	        let expected_g2 = Affine::new_unchecked(
151	            fp_from_hex!("30433263B93777D7D9AFEF0AD0C2917E183EF5A9DE026EEDA53626C7C6631B2C"),
152	            fp_from_hex!("2A2C8F6465887CEEE9EE3185F32B42829E0DFA7F6C65F0071039026018903B8B"),
153	        );
154	        let g2 = g_proj + g;
155	        let g2_affine = g2.into_affine();
156	        assert_eq!(g2_affine, expected_g2);
157	        let g2_affine = g_proj.double().into_affine();
158	        assert_eq!(g2_affine, expected_g2);
159	
160	        // Test G + (-G) = 0
161	        let neg_g = -g_proj;
162	        let zero = g_proj + neg_g;
163	        assert!(zero.is_zero());
164	    }
165	
166	    #[test]
167	    fn point_sub() {
168	        let g = Affine::<BandersnatchConfig>::generator();
169	        let g_proj: Projective<BandersnatchConfig> = g.into();
170	
171	        // Test G - G = 0
172	        let zero = g_proj - g_proj;
173	        assert!(zero.is_zero());
174	
175	        // Test 2G - G = G
176	        let g2: Projective<BandersnatchConfig> = Affine::new_unchecked(
177	            fp_from_hex!("30433263B93777D7D9AFEF0AD0C2917E183EF5A9DE026EEDA53626C7C6631B2C"),
178	            fp_from_hex!("2A2C8F6465887CEEE9EE3185F32B42829E0DFA7F6C65F0071039026018903B8B"),
179	        ).into();
180	        assert_eq!(g2 - g_proj, g_proj);
181	    }
182	}
