275	/// Ed25519 signature representation.
276	///
277	/// Signature verification libraries are expected to reject invalid
278	/// field elements at the time a signature is verified.
279	#[derive(Copy, Clone, Eq, PartialEq)]
280	pub struct Signature {
281	    /// `R` is an `EdwardsPoint`, formed by using an hash function with
282	    /// `512-bits` output to produce the digest of:
283	    ///
284	    /// * the nonce half of the `ExpandedSecretKey`, and
285	    /// * the message to be signed.
286	    ///
287	    /// This digest is then interpreted as a `Scalar` and reduced into an
288	    /// element in ℤ/lℤ.  The scalar is then multiplied by the distinguished
289	    /// basepoint to produce `R`, and `EdwardsPoint`.
290	    pub R: ProjectivePoint,
291	
292	    /// `s` is a `Scalar`, formed by using a hash function with `512-bits`
293	    /// output to produce the digest of:
294	    ///
295	    /// * the `r` portion of this `Signature`,
296	    /// * the `PublicKey` which should be used to verify this `Signature`, and
297	    /// * the message to be signed.
298	    ///
299	    /// This digest is then interpreted as a `Scalar` and reduced into an
300	    /// element in ℤ/lℤ.
301	    pub s: Scalar,
302	}
