304	impl Signature {
305	    /// Converts the signature to a 64-byte array.
306	    ///
307	    /// The first 32 bytes contain the compressed encoding of the `R` value.
308	    /// The last 32 bytes contain the canonical encoding of the `s` scalar.
309	    #[must_use]
310	    pub fn to_bytes(&self) -> [u8; SIGNATURE_LENGTH] {
311	        let mut bytes = [0u8; 64];
312	
313	        // Get the compressed representation of R
314	        let r_compressed = CompressedPointY::from(self.R.into_affine());
315	        bytes[..32].copy_from_slice(r_compressed.as_ref());
316	
317	        // Get the little-endian byte representation of s
318	        let s_bytes = self.s.into_bigint().into_bytes_le();
319	        bytes[32..].copy_from_slice(&s_bytes[..32]);
320	
321	        bytes
322	    }
