345	    /// Verify a signature on a message with this keypair's public key.
346	    #[must_use]
347	    pub fn is_valid(&self, message: &[u8], signature: &Signature) -> bool {
348	        let expected_r = self.compute_R(signature, message);
349	        expected_r == signature.R
350	    }
351	
352	    /// Helper for verification. Computes the expected `R` component of the
353	    /// signature. The caller compares this to the real `R` component.
354	    /// This computes `H(R || A || M)` where `H` is the 512-bit hash function
355	    /// given by `CtxDigest` (this is SHA-512 in spec-compliant Ed25519).
356	    fn compute_R(
357	        &self,
358	        signature: &Signature,
359	        message: &[u8],
360	    ) -> ProjectivePoint {
361	        let R = signature.R;
362	        let A = self.point;
363	
364	        let mut h = Sha512::new();
365	        h.update(CompressedPointY::from(R.into_affine()));
366	        h.update(CompressedPointY::from(A.into_affine()));
367	        h.update(message);
368	
369	        let k = WideScalar::from_bigint(U512::from_bytes_le(
370	            h.finalize().as_slice(),
371	        ));
372	        let k = Scalar::from_fp(k);
373	
374	        // Compute R: `-[k]A + [s]B = R`.
375	        A * (-k) + ProjectivePoint::generator() * signature.s
376	    }
