94	/// Sets a = a + b + carry, and returns the new carry.
95	#[inline(always)]
96	pub fn adc_assign(a: &mut Limb, b: Limb, carry: bool) -> bool {
97	    let tmp = *a as WideLimb + b as WideLimb + carry as WideLimb;
98	    *a = tmp as Limb;
99	    let carry = tmp >> Limb::BITS;
100	    carry != 0
101	}
