14	/// Computes an interface id as an associated function for the trait.
15	pub(crate) fn interface_id(
16	    _attr: &TokenStream,
17	    input: TokenStream,
18	) -> TokenStream {
19	    let mut input = parse_macro_input!(input as ItemTrait);
20	
21	    let unsafety = input.unsafety;
22	    let mut selectors_map =
23	        HashMap::<String, (String, proc_macro2::TokenStream)>::new();
24	
25	    for item in &mut input.items {
26	        let TraitItem::Fn(func) = item else {
27	            continue;
28	        };
29	
30	        let mut override_fn_name = None;
31	        for attr in mem::take(&mut func.attrs) {
32	            if attr.path().is_ident("selector") {
33	                if override_fn_name.is_some() {
34	                    error!(attr.path(), "more than one selector attribute");
35	                }
36	                let args: SelectorArgs = match attr.parse_args() {
37	                    Ok(args) => args,
38	                    Err(error) => error!(attr.path(), "{}", error),
39	                };
40	                override_fn_name = Some(args.name);
41	            } else {
42	                // Put back any other attributes.
43	                func.attrs.push(attr);
44	            }
45	        }
46	
47	        let rust_fn_name = func.sig.ident.to_string();
48	
49	        let solidity_fn_name =
50	            override_fn_name.unwrap_or(rust_fn_name.to_case(Case::Camel));
51	
52	        let arg_types = func.sig.inputs.iter().filter_map(|arg| match arg {
53	            FnArg::Typed(t) => Some(t.ty.clone()),
54	            // Opt out any `self` arguments.
55	            FnArg::Receiver(_) => None,
56	        });
57	
58	        // Build the function signature string for selector computation.
59	        let type_strings: Vec<String> =
60	            arg_types.clone().map(|ty| quote!(#ty).to_string()).collect();
61	        let signature =
62	            format!("{}({})", solidity_fn_name, type_strings.join(","));
63	
64	        let selector = quote! { alloy_primitives::aliases::B32::new(stylus_sdk::function_selector!(#solidity_fn_name #(, #arg_types )*)) };
65	
66	        // Store selector expression from every function in the trait.
67	        match selectors_map.get(&signature) {
68	            Some((existing_rust_fn_name, _)) => {
69	                error!(
70	                    existing_rust_fn_name,
71	                    "selector collision detected: function '{}' has the same selector as function '{}': {}",
72	                    rust_fn_name,
73	                    existing_rust_fn_name,
74	                    signature,
75	                );
76	            }
77	            None => selectors_map.insert(signature, (rust_fn_name, selector)),
78	        };
79	    }
80	
81	    let name = input.ident;
82	    let vis = input.vis;
83	    let attrs = input.attrs;
84	    let trait_items = input.items;
85	    let generics = input.generics.clone();
86	    let where_clause = &generics.where_clause;
87	
88	    let supertrait_tokens = if input.supertraits.is_empty() {
89	        quote! {}
90	    } else {
91	        let supertraits = &input.supertraits;
92	        quote! { : #supertraits }
93	    };
94	
95	    let selectors = selectors_map.values().map(|(_, tokens)| tokens);
96	
97	    // Keep the same trait with an additional associated function
98	    // `interface_id`.
99	    quote! {
100	        #(#attrs)*
101	        #vis #unsafety trait #name #generics #supertrait_tokens #where_clause {
102	            #(#trait_items)*
103	
104	            #[doc = concat!("Solidity interface id associated with ", stringify!(#name), " trait.")]
105	            #[doc = "Computed as a XOR of selectors for each function in the trait."]
106	            fn interface_id() -> alloy_primitives::aliases::B32
107	            where
108	                Self: Sized,
109	            {
110	                #(#selectors)^*
111	            }
112	        }
113	    }
114	    .into()
115	}
