53	impl Erc721UriStorage {
54	    /// Sets `token_uri` as the token URI of `token_id`.
55	    ///
56	    /// # Arguments
57	    ///
58	    /// * `&mut self` - Write access to the contract's state.
59	    /// * `token_id` - Id of a token.
60	    /// * `token_uri` - URI for the token.
61	    ///
62	    /// # Events
63	    ///
64	    /// * [`MetadataUpdate`].
65	    pub fn _set_token_uri(&mut self, token_id: U256, token_uri: String) {
66	        self.token_uris.setter(token_id).set_str(token_uri);
67	        evm::log(MetadataUpdate { token_id });
68	    }
