70	    /// Check [`IErc721Metadata::token_uri()`] for more details.
71	    #[allow(clippy::missing_errors_doc)]
72	    pub fn token_uri(
73	        &self,
74	        token_id: U256,
75	        erc721: &impl IErc721<Error = erc721::Error>,
76	        metadata: &Erc721Metadata,
77	    ) -> Result<String, erc721::Error> {
78	        erc721.owner_of(token_id)?;
79	
80	        let token_uri = self.token_uris.getter(token_id).get_string();
81	        let base = metadata.base_uri();
82	
83	        // If there is no base URI, return the token URI.
84	        if base.is_empty() {
85	            return Ok(token_uri);
86	        }
87	
88	        // If both are set, concatenate the `base_uri` and `token_uri`.
89	        let uri = if token_uri.is_empty() {
90	            metadata.token_uri(token_id, erc721)?
91	        } else {
92	            base + &token_uri
93	        };
94	
95	        Ok(uri)
96	    }
